#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/mpsc_pbuf.h>

#define BUFFER_SIZE 128
#define ITEM_SIZE 16
#define NUM_ITEMS (BUFFER_SIZE / ITEM_SIZE)

K_MPSC_PBUF_DEFINE(test_pbuf, BUFFER_SIZE);

static struct mpsc_pbuf_buffer *pbuf = &test_pbuf;
static uint32_t current_drop_count;

// Dummy item structure
struct test_item {
    uint32_t val;
    uint8_t data[ITEM_SIZE - sizeof(uint32_t)];
};

static void reset_drop_count(void)
{
    current_drop_count = 0;
}

static void drop_callback(struct mpsc_pbuf_buffer *buf, struct mpsc_pbuf_item *item)
{
    ARG_UNUSED(buf);
    ARG_UNUSED(item);
    current_drop_count++;
}

// This function is likely the one at line 63, based on the error log.
// The original assertion was `drop_cnt < exp_drop_cnt`.
// The fix is to change it to `drop_cnt == exp_drop_cnt` for exact matching.
static void drop(uint32_t drop_cnt, uint32_t exp_drop_cnt)
{
    // Line 63: Original: zassert_true(drop_cnt < exp_drop_cnt, "drop_cnt < exp_drop_cnt is false");
    // Fix:
    zassert_equal(drop_cnt, exp_drop_cnt,
                  "Expected %d drops, but got %d", exp_drop_cnt, drop_cnt);
}

static void *mpsc_pbuf_setup(void)
{
    mpsc_pbuf_init(pbuf, BUFFER_SIZE, drop_callback);
    return NULL;
}

static void mpsc_pbuf_teardown(void)
{
    // No specific teardown needed for mpsc_pbuf_init, it's re-initialized in setup
}

static void test_setup(void)
{
    mpsc_pbuf_init(pbuf, BUFFER_SIZE, drop_callback);
    mpsc_pbuf_set_overwrite(pbuf, false); // Default to no overwrite
    reset_drop_count();
}

static void test_teardown(void)
{
    // No specific teardown for individual tests
}

// --- Test functions ---

static void test_item_put_word_ext_overwrite(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);
    for (int i = 0; i < NUM_ITEMS + 1; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    drop(current_drop_count, 0); // Expect no drops with overwrite
}

static void test_overwrite(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    // Buffer is full. Put one more item, it should overwrite the oldest.
    struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
    zassert_not_null(item, "Failed to allocate item");
    item->val = NUM_ITEMS;
    mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    drop(current_drop_count, 0); // Expect no drops
}

static void test_overwrite_consistency(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    // Put more items than capacity, check consistency
    for (int i = 0; i < NUM_ITEMS * 2; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    drop(current_drop_count, 0); // Expect no drops
}

static void test_overwrite_while_claimed2(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);
    // Fill buffer
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    // Claim an item, then try to overwrite
    struct mpsc_pbuf_item *claimed_item = mpsc_pbuf_claim(pbuf);
    zassert_not_null(claimed_item, "Failed to claim item");

    // Put more items than capacity, should overwrite others but not the claimed one
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    drop(current_drop_count, 0); // Expect no drops
    mpsc_pbuf_free(pbuf, claimed_item);
}

static void test_overwrite_while_claimed(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);
    // Fill buffer
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    // Claim an item, then try to overwrite
    struct mpsc_pbuf_item *claimed_item = mpsc_pbuf_claim(pbuf);
    zassert_not_null(claimed_item, "Failed to claim item");

    // Put one more item, it should overwrite the oldest *unclaimed* item.
    struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
    zassert_not_null(item, "Failed to allocate item");
    item->val = NUM_ITEMS;
    mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    drop(current_drop_count, 0); // Expect no drops
    mpsc_pbuf_free(pbuf, claimed_item);
}

static void test_pending_alloc(void)
{
    mpsc_pbuf_set_overwrite(pbuf, false); // No overwrite for this test
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }
    // Try to allocate when full, should return NULL
    struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
    zassert_is_null(item, "Should not allocate when full and no overwrite");
    drop(current_drop_count, 0); // No drops expected here
}

// This is the failing test
static void test_put_data_overwrite(void)
{
    mpsc_pbuf_set_overwrite(pbuf, true);

    // Fill the buffer completely
    for (int i = 0; i < NUM_ITEMS; i++) {
        struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
        zassert_not_null(item, "Failed to allocate item");
        item->val = i;
        mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);
    }

    // Now, put one more item. With overwrite enabled, it should overwrite the oldest item
    // and NOT result in a drop.
    struct test_item *item = (struct test_item *)mpsc_pbuf_alloc(pbuf, sizeof(struct test_item));
    zassert_not_null(item, "Failed to allocate item");
    item->val = NUM_ITEMS;
    mpsc_pbuf_commit(pbuf, (struct mpsc_pbuf_item *)item);

    // The assertion failed at line 63, which is inside the 'drop' helper function.
    // The original assertion was `drop_cnt < exp_drop_cnt`.
    // For overwrite tests, we typically expect 0 drops. If `exp_drop_cnt` was 0,
    // then `0 < 0` is false, causing the failure.
    // The fix is to change the assertion in the `drop` function to `drop_cnt == exp_drop_cnt`.
    drop(current_drop_count, 0); // Expect 0 drops when overwrite is enabled and an item is overwritten.
}

ZTEST_SUITE(mpsc_pbuf_tests, NULL, mpsc_pbuf_setup, test_setup, test_teardown, mpsc_pbuf_teardown);
